import time
import logging

from ute_ue.data_transfers.lte_data_transfer import LteDataTransfer
from .exceptions import (ScenarioMessageCannotMatch, CannotStartTraffic,
                         scenario_message_exception)
from .iperf.iperf_commands import IperfUpLinkCommand, IperfDownLinkCommand


class PrismaDataTransfer(LteDataTransfer):
    def __init__(self, alias, dt_definition, configuration, checkthroughput,
                 prisma, logger_name='taf_ue'):
        """
                Basic initialization.

                :param alias: Alias to be assigned to DataTransfer object
                :param dt_definition: DataTransferDefinition object - definition of data transfer characteristics
                :param configuration: tool dependant configuration provided by UE instance
                needed for data transfer operations
                """
        super(PrismaDataTransfer, self).__init__(alias, dt_definition, configuration, logger_name)
        self._prisma = prisma
        self._throughput = checkthroughput
        logging.debug("Data transfer configuration: {}".format(self._configuration))

    def start(self):
        """
        Start data transfer with parameters defined in dt_definition passed during initialization.

        :return: None
        """
        self._prisma.traffic_start()
        self._wait_traffic_started()
        self._throughput.setup()

    def stop(self):
        """
        Stop already running data transfer.

        Fires exception if given data transfer (selected by it's name) was not started yet.
        No action if given data transfer is already finished.
        :return: None
        """
        self._prisma.traffic_stop()
        self._check_execute_finished()

    def release_iperf_process(self):
        """
        Release Iperf process if needed.

        :return:
        """
        pass

    def await_finish(self):
        while True:
            scenario = self._prisma.get_scenario_status()
            if scenario == "SCENARIO_COMPLETED":
                logging.info("Data traffic finished. {}".format(scenario))
                break
            logging.debug("Traffic running, wait 10s. {}".format(scenario))
            time.sleep(10)

    def is_running(self):
        """
        Check if data transfer is running

        :return: boolean
        """
        scenario = self._prisma.get_scenario_status()
        logging.info("Checking Scenario running status: {}".format(scenario))
        if scenario == "RUNNING_SCENARIO":
            return True
        else:
            logging.info("Scenario not running.")
            return False

    def check_data_transfer(self):

        running = self.is_running()
        throughput = self.get_average_throughput()
        if throughput > 0 and running:
            logging.info("Traffic alive, current average throughput: {} kbits/s".format(throughput))
            return True
        else:
            raise Exception("Traffic not alive. current average throughput: {} kbits/s".format(throughput))

    def reset_statistics(self):
        """
        Reset data transfer statistics on UE.

        :return: None
        :raises: :py:class:`ute_common_abstract_core.exceptions.UnknownAlias`:
        if no such dt_name created before via start_data_transfer
        :raises: :py:class:`ute_common_abstract_core.exceptions.WrongAlias`:
        if dt_name doesn't point to DataTransfer object
        :raises: :py:class:`ute_ue.exceptions.UeProcedureError`:
        If reset data transfer statistics failed
        """
        raise NotImplementedError

    def get_average_throughput(self, omit=0):
        """
        Abstract method for getting average throughput of data transfer.
        Average throughput is measured from 'dt.start()' to current time or from
        'dt.start()' to 'dt.stop()' if data transfer is already finished

        :param omit: it is a delay in seconds to start counting the tput ex. '20' - 1st 20 seconds of datatransfer will be omitted.
        :return: value of Average throughput in unit: Kbits/sec
        """
        if omit:
            raise TypeError("Parameter 'omit' is currently not supported by taf.ue.plugin.prisma")
        return self._throughput.calculate_throughoutput()

    def _wait_traffic_started(self):
        raise NotImplementedError

    def get_datagram_loss(self):
        """
        Getting datagram loss of UDP data transfer
        :return: value of datagram loss in %
        """
        raise NotImplementedError

    def _wait_matched_logger(self, pattern, timeout=120):
        for _ in range(timeout):
            sce_logger = str(self._prisma.get_scenario_logger())
            if pattern in sce_logger:
                break
            time.sleep(1)
        else:
            sce_logger = str(self._prisma.get_scenario_logger())
            raise ScenarioMessageCannotMatch(pattern, sce_logger, timeout=timeout)
        logging.info("Airmosaic scenario log: {}".format(sce_logger))

    def _check_execute_finished(self):
        logging.info("Getting scenario to confirm execute finished.")
        check_count = 0
        while True:
            scenario = self._prisma.get_scenario_status()
            if scenario == "SCENARIO_COMPLETED":
                logging.info("SCENARIO_COMPLETED")
                break
            elif scenario == "SCENARIO_AVAILABLE":
                logging.warning("Airmosaic turn into SCENARIO_AVAILABLE, not SCENARIO_COMPLETED.")
                break
            check_count += 1
            logging.info("{}, check again in 30s. Check times = {}".format(scenario, check_count))
            time.sleep(30)


class PrismaUDGUpLinkDataTransfer(PrismaDataTransfer):
    """Object responsible for managing data transfer."""

    def __init__(self, alias, dt_definition, configuration, checkthroughput,
                 prisma, logger_name='taf_ue'):
        """

        :param alias: Alias to be assigned to DataTransfer object
        :param dt_definition: DataTransferDefinition object - definition of data transfer characteristics
        :param configuration: tool dependant configuration provided by UE instance needed for data transfer operations
        """
        super(PrismaUDGUpLinkDataTransfer, self).__init__(alias,
                                                          dt_definition,
                                                          configuration,
                                                          checkthroughput,
                                                          prisma,
                                                          logger_name)

    def _wait_traffic_started(self):
        self._await_ul_traffic_started()

    @scenario_message_exception(CannotStartTraffic)
    def _await_ul_traffic_started(self):
        logging.info("Await until up link traffic started in Airmosaic.")
        pattern = "Procedure UDG Monodirectional transmission Uplink started"
        self._wait_matched_logger(pattern)
        logging.info("Up link Traffic started.")


