class PrismaUDGUpDownLinkDataTransfer(PrismaDataTransfer):
    """Object responsible for managing data transfer."""

    def __init__(self, alias, dt_definition, configuration,
                 ul_checkthroughput, dl_checkthroughput,
                 prisma, logger_name='taf_ue'):
        """

        :param alias: Alias to be assigned to DataTransfer object
        :param dt_definition: DataTransferDefinition object - definition of data transfer characteristics
        :param configuration: tool dependant configuration provided by UE instance needed for data transfer operations
        """
        super(PrismaUDGUpDownLinkDataTransfer, self).__init__(alias,
                                                              dt_definition,
                                                              configuration,
                                                              (ul_checkthroughput, dl_checkthroughput),
                                                              prisma,
                                                              logger_name)

    def start(self):
        """
        Start data transfer with parameters defined in dt_definition passed during initialization.

        :return: None
        """
        self._prisma.traffic_start()
        self._wait_traffic_started()
        for throughput in self._throughput:
            throughput.setup()

    def _wait_traffic_started(self):
        self._wait_dl_traffic_started()

    @scenario_message_exception(CannotStartTraffic)
    def _wait_dl_traffic_started(self):
        logging.info("Await until up link traffic started in Airmosaic.")
        pattern = "Procedure UDG Monodirectional transmission Uplink started"
        self._wait_matched_logger(pattern)
        logging.info("Up link Traffic started.")

        logging.info("Await until down link traffic started in Airmosaic.")
        pattern = "Procedure UDG Monodirectional transmission Downlink started"
        self._wait_matched_logger(pattern)
        logging.info("Down link Traffic started.")

    def get_average_throughput(self, omit=0):
        """
        Abstract method for getting average throughput of data transfer.
        Average throughput is measured from 'dt.start()' to current time or from
        'dt.start()' to 'dt.stop()' if data transfer is already finished

        :param omit: it is a delay in seconds to start counting the tput ex. '20' - 1st 20 seconds of datatransfer will be omitted.
        :return: value of Average throughput in unit: Kbits/sec
        """
        if omit:
            raise TypeError("Parameter 'omit' is currently not supported by taf.ue.plugin.prisma")
        ul_tput = self._throughput[0].calculate_throughoutput()
        dl_tput = self._throughput[1].calculate_throughoutput()
        total_tput = ul_tput + dl_tput
        logging.info("Getting UL and DL throughput at the same time.\n"
                     "UL throughput:{UL}Kbits/sec\n"
                     "DL throughput:{DL}Kbits/sec\n"
                     "Total throughput:{total_tput}Kbits/sec\n".format(UL=ul_tput,
                                                                       DL=dl_tput,
                                                                       total_tput=total_tput))
        return total_tput


class PrismaIperfUpLinkDataTransfer(PrismaDataTransfer):
    """Object responsible for managing data transfer."""

    def __init__(self, alias, dt_definition, configuration, checkthroughput,
                 prisma, logger_name='taf_ue'):
        """

        :param alias: Alias to be assigned to DataTransfer object
        :param dt_definition: DataTransferDefinition object - definition of data transfer characteristics
        :param configuration: tool dependant configuration provided by UE instance needed for data transfer operations
        """
        super(PrismaIperfUpLinkDataTransfer, self).__init__(alias,
                                                            dt_definition,
                                                            configuration,
                                                            checkthroughput,
                                                            prisma,
                                                            logger_name)
        self._iperf_ul_dt_cmd = IperfUpLinkCommand(dt_definition, configuration)

    def stop(self):
        """
        Stop already running data transfer.

        Fires exception if given data transfer (selected by it's name) was not started yet.
        No action if given data transfer is already finished.
        :return: None
        """
        self.release_iperf_process()
        logging.debug("Stopped Iperf process, executing traffic stop.")
        self._prisma.traffic_stop()
        self._check_execute_finished()
        self._iperf_ul_dt_cmd.teardown()

    def release_iperf_process(self):
        logging.info("Tring to release iperf process.")
        self._iperf_ul_dt_cmd.stop_iperf_cmd()
        logging.info("Iperf process released.")

    def _wait_traffic_started(self):
        self._await_ul_traffic_started()

    @scenario_message_exception(CannotStartTraffic)
    def _await_ul_traffic_started(self):
        logging.info("Await until IP Passthrough and Delay scenarios started in Airmosaic.")
        # step1: Airmosaic run IP Passthrough start and Delay scenarios
        # step2: ping through from EPC to Prisma application PC
        # step3: run iperf up link traffic command
        # step4: run iperf stop command
        # step5: calculate throughput
        pattern = "IP Passthrough start:UEMNG-ip_passthrough_start_cmpl"
        self._wait_matched_logger(pattern)
        logging.info("IP Passthrough started.")

        self._iperf_ul_dt_cmd.check_ip_pass_through()
        self._iperf_ul_dt_cmd.start_iperf_cmd()
        logging.info("Up link Traffic started.")


